import json, importlib, sys
from pathlib import Path

root = Path.cwd()
sys.path.insert(0, str(root))
failures = []
for path in sorted((root / "examples").glob("*.json")):
    service = path.stem
    mod = importlib.import_module(f"clients.{service}")
    cases = json.loads(path.read_text())
    for i, case in enumerate(cases):
        rec = case["record"]
        expected = case["result"]
        if "err" in expected:
            try:
                got = mod.normalize(dict(rec))
            except ValueError:
                pass
            except Exception as exc:
                failures.append((service, i, f"wrong exception {type(exc).__name__}: {exc}"))
            else:
                failures.append((service, i, f"expected {expected['err']}, got ok {got}"))
        else:
            try:
                got = mod.normalize(dict(rec))
            except Exception as exc:
                failures.append((service, i, f"unexpected {type(exc).__name__}: {exc}"))
                continue
            if got != expected["ok"]:
                failures.append((service, i, {"missing": {k: v for k, v in expected["ok"].items() if k not in got or got[k] != v}, "extra": {k: v for k, v in got.items() if k not in expected["ok"]}}))
print(f"{len(failures)} failures")
for f in failures:
    print(f)

