import json, sys, importlib
from pathlib import Path
sys.path.insert(0, str(Path.cwd()))

order_mismatch = []
for path in sorted((Path.cwd() / "examples").glob("*.json")):
    mod = importlib.import_module(f"clients.{path.stem}")
    for i, case in enumerate(json.loads(path.read_text())):
        if "ok" not in case["result"]:
            continue
        got = mod.normalize(case["record"])
        exp = case["result"]["ok"]
        if list(got) != list(exp):
            order_mismatch.append((path.stem, i, list(got), list(exp)))
print("order mismatches:", order_mismatch)

from clients._rules import cents, iso_date, split_field, to_bool
r = {"c": "2.345", "d": " 1 / 2 / 2020 ", "s": " a ;; b ", "b": " YES "}
cents(r, "c"); iso_date(r, "d"); split_field(r, "s", ";"); to_bool(r, "b")
print(r)
for rec, fn, field, val in [
    ({}, cents, "x", ""), ({}, to_bool, "x", "2"), ({}, iso_date, "x", "2020-01-01"),
]:
    rec = {field: val}
    try:
        fn(rec, field); print("no error", rec)
    except Exception as e:
        print("error", type(e).__name__)

